-- 000056_backfill_moves_is_derived_third_wave.up.sql
-- M14-03e: 第三波 6 キャラの is_derived backfill(CSV に載る code のみ UPDATE)
-- 本ファイルは cmd/seedgen が character_data/*.csv から生成した成果物(手編集しない)。
-- CSV で is_derived=true の code のみ UPDATE する(触れない行は既定値 false のまま正しく振る舞う
-- ＝ユーザー生成行〔画面18 追加・rush-variant 生成〕に触れない。CHANGE-069 §2.1-d/-e)。
-- 既存マイグレは非改変(新規連番で追加)。

-- ===== m_bison (34 moves) =====
UPDATE moves SET is_derived = 1
WHERE character_id IN (SELECT c.id FROM characters c WHERE c.code = 'm_bison' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6'))
  AND code IN ('mine_set_light_psycho_crusher_attack', 'mine_set_medium_psycho_crusher_attack', 'mine_set_heavy_psycho_crusher_attack', 'mine_set_od_psycho_crusher_attack', 'mine_set_light_backfist_combo', 'mine_set_medium_backfist_combo', 'mine_set_heavy_backfist_combo', 'mine_set_od_backfist_combo', 'head_press_od', 'head_press', 'somersault_skull_diver', 'devil_reverse_od', 'mine_set_od_devil_reverse', 'devil_reverse', 'mine_set_devil_reverse', 'psycho_mine_auto_detonation', 'shadow_hammer', 'shadow_spear', 'hell_attack', 'rush_standing_light_punch', 'rush_standing_light_kick', 'rush_standing_medium_punch', 'rush_standing_medium_kick', 'rush_standing_heavy_punch', 'rush_standing_heavy_kick', 'rush_crouching_light_punch', 'rush_crouching_light_kick', 'rush_crouching_medium_punch', 'rush_crouching_medium_kick', 'rush_crouching_heavy_punch', 'rush_crouching_heavy_kick', 'rush_psycho_hammer', 'rush_evil_knee', 'rush_hover_kick');

